// @generated by the slice schematic from its spec. Edit in place; reshape via the spec and --force.
import { z } from 'zod';
import type { FormFieldMeta } from '../forms/form-field-meta';

export const heroSchema = z.object({
  name: z
    .string()
    .min(1, 'Name is required')
    .meta({ label: 'Name', control: 'text', placeholder: 'Hero name' } satisfies FormFieldMeta),
  alias: z
    .string()
    .min(1, 'Alias is required')
    .meta({
      label: 'Alias',
      control: 'text',
      placeholder: 'Civilian name or Unknown',
    } satisfies FormFieldMeta),
  powerClass: z.enum(['Aerial', 'Energy', 'Psionic', 'Tech', 'Mutant', 'Cosmic', 'Enhanced']).meta({
    label: 'Class',
    control: 'select',
    placeholder: 'Select a class',
    options: [
      { value: 'Aerial', label: 'Aerial' },
      { value: 'Energy', label: 'Energy' },
      { value: 'Psionic', label: 'Psionic' },
      { value: 'Tech', label: 'Tech' },
      { value: 'Mutant', label: 'Mutant' },
      { value: 'Cosmic', label: 'Cosmic' },
      { value: 'Enhanced', label: 'Enhanced' },
    ],
  } satisfies FormFieldMeta),
  power: z
    .number()
    .min(0, 'Power index must be at least 0')
    .max(100, 'Power index must not exceed 100')
    .meta({
      label: 'Power index',
      control: 'number',
      help: 'Power index, 0 to 100.',
    } satisfies FormFieldMeta),
  status: z.enum(['Active', 'Injured', 'Reserve', 'MIA']).meta({
    label: 'Status',
    control: 'select',
    placeholder: 'Select a status',
    options: [
      { value: 'Active', label: 'Active' },
      { value: 'Injured', label: 'Injured' },
      { value: 'Reserve', label: 'Reserve' },
      { value: 'MIA', label: 'MIA' },
    ],
  } satisfies FormFieldMeta),
  notes: z.string().meta({
    label: 'Notes',
    control: 'textarea',
    placeholder: 'Field notes',
  } satisfies FormFieldMeta),
});

export type HeroFormModel = z.infer<typeof heroSchema>;
